code_sketch:
let ctx = container.newBackgroundContext()
ctx.perform {
    let item = ctx.object(with: id) as! Item
    item.title = "first"       // tracked, no store write
    item.updatedAt = .now      // coalesced into the same UPDATE
    do { try ctx.save() }      // one atomic write at the boundary
    catch { ctx.rollback() }
}

